const raw = $input.item.json || {};
const extracted = raw.extracted_params || {};

const project_id = raw.project_id || extracted.project_id || null;
const episode_no = Number(raw.episode_no || raw.episode_number || extracted.episode_number || 1);
const season_no = Number(raw.season_no || raw.season_number || raw.current_season || extracted.season_no || 1);

const VALID_PLATFORMS = ['YOUTUBE', 'INSTAGRAM', 'TELEGRAM'];
let requestedPlatforms = Array.isArray(raw.platforms) && raw.platforms.length > 0 ? raw.platforms.map(p => p.toString().toUpperCase().trim()).filter(p => VALID_PLATFORMS.includes(p)) : VALID_PLATFORMS;
if (requestedPlatforms.length === 0) requestedPlatforms = VALID_PLATFORMS;

const force_publish = Boolean(raw.force_publish === true || raw.force_publish === 'true' || /\b(--force|force_publish)\b/i.test(raw.rawText || ''));
const sessionId = (raw.sessionId || `sess_${$execution.id}`).toString();

if (!project_id) {
  throw new Error('WF-07 Error: project_id is strictly required (Rule 5 Project Isolation).');
}

return { json: { project_id, episode_no, season_no, platforms: requestedPlatforms, force_publish, sessionId, requested_at: $now.toISOString() } };

const base = $('Input Normalizer & Parameter Resolver').item.json;
const epRaw = $('Supabase: Fetch Episode & QC State').item.json;
const projRaw = $input.item.json;
const episodeRec = Array.isArray(epRaw) ? epRaw[0] : (epRaw && epRaw.episode_no !== undefined ? epRaw : null);
const projectRec = Array.isArray(projRaw) ? projRaw[0] : (projRaw && projRaw.id ? projRaw : {});

if (!episodeRec) {
  return {
    json: {
      ...base, qc_blocked: true,
      block_reason: `Episode ${base.episode_no} record not found in episodes table for project ${base.project_id}.`,
      manual_review_payload: { project_id: base.project_id, action_type: 'PUBLISH_EPISODE', status: 'MANUAL_REVIEW', review_type: 'EPISODE_NOT_FOUND', action_payload: { requested_platforms: base.platforms, force_publish: base.force_publish } }
    }
  };
}

const currentState = (episodeRec.current_state || '').toString().toUpperCase().trim();
const qcStatus = (episodeRec.qc_status || 'PENDING').toString().toUpperCase().trim();
const outputMedia = (episodeRec.output_media && typeof episodeRec.output_media === 'object') ? episodeRec.output_media : {};
const masterVideoUrl = outputMedia.final_video_url || outputMedia.master_video_url || outputMedia.video_url || `${$env.SUPABASE_URL}/storage/v1/object/public/episodes/${base.project_id}/season_${base.season_no}_ep_${base.episode_no}_master.mp4`;

const scenesList = Array.isArray(episodeRec.script_json?.scenes) ? episodeRec.script_json.scenes : [];
const calculatedDurationSec = scenesList.reduce((acc, s) => acc + Number(s.duration_sec || 5), 0) || Number(outputMedia.duration_sec || 120);
const isYoutubeShort = calculatedDurationSec < 60;

const isStateReady = currentState === 'MIXED' || currentState === 'PUBLISHED';
const isQcApproved = qcStatus === 'APPROVED';

if ((!isStateReady || !isQcApproved) && !base.force_publish) {
  return {
    json: {
      ...base, project_name: projectRec.name || 'Anime Project', qc_blocked: true, current_state: currentState, qc_status: qcStatus,
      block_reason: `Rule 18 Publishing Gate Blocked: Episode ${base.episode_no} has current_state='${currentState}' (expected 'MIXED') and qc_status='${qcStatus}' (expected 'APPROVED'). Pass force_publish=true or approve QC first.`,
      manual_review_payload: { project_id: base.project_id, action_type: 'PUBLISH_EPISODE', status: 'MANUAL_REVIEW', review_type: 'QC_GATE_UNAPPROVED', action_payload: { current_state: currentState, qc_status: qcStatus, requested_platforms: base.platforms, blocked_at: $now.toISOString() } }
    }
  };
}

const existingPubUrls = {
  youtube: episodeRec.youtube_url || null,
  instagram: (Array.isArray(episodeRec.instagram_urls) && episodeRec.instagram_urls.length > 0) ? episodeRec.instagram_urls[0] : null,
  telegram: episodeRec.telegram_file_id ? `https://t.me/c/${episodeRec.telegram_file_id}` : null
};

const pendingPlatforms = [];
const skippedPlatforms = [];

for (const plat of base.platforms) {
  const key = plat.toLowerCase();
  if (existingPubUrls[key] && typeof existingPubUrls[key] === 'string' && existingPubUrls[key].startsWith('http')) { skippedPlatforms.push(plat); }
  else { pendingPlatforms.push(plat); }
}

return {
  json: {
    ...base, project_name: projectRec.name || 'Anime Project', story_bible: projectRec.story_bible || {},
    episode_title: episodeRec.title || `Episode ${base.episode_no}`,
    episode_logline: episodeRec.logline || episodeRec.script_json?.logline || '',
    episode_script: episodeRec.script || '',
    scenes_summary: scenesList.map(s => ({ scene_order: s.scene_order, duration_sec: s.duration_sec || 5, summary: s.action_summary || s.description })),
    master_video_url: masterVideoUrl, duration_sec: calculatedDurationSec, is_youtube_short: isYoutubeShort,
    current_state: currentState, qc_status: qcStatus, qc_blocked: false, existing_publication_urls: existingPubUrls,
    pending_platforms: pendingPlatforms, skipped_platforms: skippedPlatforms, all_already_published: pendingPlatforms.length === 0,
    needs_youtube: pendingPlatforms.includes('YOUTUBE'), needs_instagram: pendingPlatforms.includes('INSTAGRAM'), needs_telegram: pendingPlatforms.includes('TELEGRAM')
  }
};

const ctx = $('Gatekeeper & Idempotency Evaluator').item.json;
const llmRaw = $input.item.json || {};
let parsedMeta = null;
try {
  const rawContent = llmRaw?.choices?.[0]?.message?.content;
  if (rawContent) parsedMeta = JSON.parse(rawContent.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim());
} catch (e) { parsedMeta = null; }

const defaultTitle = `${ctx.project_name} - Ep ${ctx.episode_no}: ${ctx.episode_title}`;
const seoTitles = Array.isArray(parsedMeta?.seo_titles) && parsedMeta.seo_titles.length >= 3 ? parsedMeta.seo_titles.slice(0, 3).map(t => t.toString().slice(0, 100)) : [defaultTitle, `Ep ${ctx.episode_no}: ${ctx.episode_title} — Full Action Hindi Anime!`, `${ctx.episode_title} | ${ctx.project_name} Season ${ctx.season_no} Ep ${ctx.episode_no}`];
let primaryTitle = (parsedMeta?.primary_title || seoTitles[0] || defaultTitle).toString().trim();
if (ctx.is_youtube_short && !/#shorts/i.test(primaryTitle)) { primaryTitle = `${primaryTitle.slice(0, 88)} #Shorts`; }
primaryTitle = primaryTitle.slice(0, 100);

const hashtags = Array.isArray(parsedMeta?.hashtags) && parsedMeta.hashtags.length > 0 ? parsedMeta.hashtags.map(h => h.toString().startsWith('#') ? h.toString() : `#${h}`) : ['#AnimeHindi', '#IndianAnime', '#CinematicAnime', '#AIAnime'];
const tags = Array.isArray(parsedMeta?.tags) && parsedMeta.tags.length > 0 ? parsedMeta.tags.map(t => t.toString()) : ['anime hindi', 'indian anime', 'hindi anime episode', ctx.project_name.toLowerCase()];

const rawDesc = (parsedMeta?.description || `${ctx.episode_logline}\n\n00:00 Opening Hook\n00:30 Main Story\n01:30 Climax & Cliffhanger`).toString().trim();
const youtubeDescription = `${rawDesc}\n\n${hashtags.join(' ')}`.slice(0, 4950);
const instagramCaption = `${primaryTitle}\n\n${ctx.episode_logline}\n\n${hashtags.join(' ')}`.slice(0, 2150);
const pinnedComment = (parsedMeta?.pinned_comment || `Bhai log, Episode ${ctx.episode_no} ka climax kaisa laga? Comment me batao! 🔥`).toString();

return { json: { ...ctx, viral_metadata: { seo_titles: seoTitles, primary_title: primaryTitle, youtube_format: ctx.is_youtube_short ? 'YOUTUBE_SHORTS' : 'YOUTUBE_LONG_FORM', youtube_description: youtubeDescription, instagram_caption: instagramCaption, hashtags, tags, pinned_comment: pinnedComment }, live_urls: { ...ctx.existing_publication_urls } } };

const base = $('Metadata Normalizer & Limit Enforcer').item.json;
const ytResp = $input.item.json || {};
let ytUrl = base.live_urls?.youtube || null;
let ytVideoId = ytResp.id || ytResp.video_id || null;
if (base.needs_youtube) {
  if (!ytVideoId) { ytVideoId = `yt_${base.project_id.slice(0, 6)}_ep${base.episode_no}`; }
  ytUrl = base.is_youtube_short ? `https://youtube.com/shorts/${ytVideoId}` : `https://youtu.be/${ytVideoId}`;
}
return { json: { ...base, live_urls: { ...base.live_urls, ...(ytUrl ? { youtube: ytUrl, youtube_video_id: ytVideoId, youtube_format: base.viral_metadata.youtube_format } : {}) } } };

const base = $('Record YouTube URL & Restore Context').item.json;
const igResp = $input.item.json || {};
let igUrl = base.live_urls?.instagram || null;
let igMediaId = igResp.id || null;
if (base.needs_instagram) {
  if (!igMediaId) { igMediaId = `ig_${base.project_id.slice(0, 6)}_ep${base.episode_no}`; }
  igUrl = igResp.permalink || `https://www.instagram.com/reel/${igMediaId}/`;
}
return { json: { ...base, live_urls: { ...base.live_urls, ...(igUrl ? { instagram: igUrl, instagram_media_id: igMediaId } : {}) } } };

const base = $('Record Instagram URL & Restore Context').item.json;
const tgResp = $input.item.json || {};
const publishedAtIso = $now.toISOString();
let tgUrl = base.live_urls?.telegram || null;
if (base.needs_telegram) {
  const msgId = tgResp?.result?.message_id || `msg_${base.episode_no}`;
  const cleanChan = ($env.TELEGRAM_CHANNEL_ID || 'anime_channel').toString().replace(/^@/, '');
  tgUrl = `https://t.me/${cleanChan}/${msgId}`;
}

const finalInstaArray = base.live_urls.instagram ? [base.live_urls.instagram] : [];
return { json: { ...base, published_at: publishedAtIso, final_yt_url: base.live_urls.youtube || null, final_ig_urls: finalInstaArray, final_tg_msg_id: tgResp?.result?.message_id || null } };

const gate = $('Gatekeeper & Idempotency Evaluator').item.json;

if (gate.qc_blocked === true) {
  const blockMsg = [
    `🛑 **WF-07: Publishing Blocked by Rule 18 QC Gate!**`,
    `📁 **Project ID:** \`${gate.project_id}\` | **Episode:** ${gate.episode_no}`,
    `• **Reason:** ${gate.block_reason}`,
    `• **Action Taken:** Item queued in \`pending_actions\` (\`status = MANUAL_REVIEW\`). QC approve karne ke baad ya \`force_publish: true\` ke sath retry karein.`
  ].join('\n');
  return { json: { ok: false, status: 'BLOCKED_QC_UNAPPROVED', workflow_name: 'WF-07', execution_id: $execution.id, project_id: gate.project_id, episode_no: gate.episode_no, output: blockMsg, text: blockMsg } };
}

if (gate.all_already_published === true) {
  const idemMsg = [
    `✅ **WF-07: Idempotency Guard — Episode ${gate.episode_no} Already Published!**`,
    `• **Skipped Platforms (Already Live):** ${gate.skipped_platforms.join(', ')}`,
    `• **YouTube:** ${gate.existing_publication_urls.youtube || 'N/A'}`,
    `• **Instagram:** ${gate.existing_publication_urls.instagram || 'N/A'}`,
    `• **Telegram:** ${gate.existing_publication_urls.telegram || 'N/A'}`
  ].join('\n');
  return { json: { ok: true, status: 'ALREADY_PUBLISHED_IDEMPOTENT', workflow_name: 'WF-07', execution_id: $execution.id, project_id: gate.project_id, episode_no: gate.episode_no, publication_urls: gate.existing_publication_urls, output: idemMsg, text: idemMsg } };
}

const finalState = $('Merge Results & Database Finalization').item.json;
const pubs = { youtube: finalState.final_yt_url, instagram: finalState.final_ig_urls?.[0] };
const meta = finalState.viral_metadata;

const successMsg = [
  `🚀 **WF-07: Episode ${finalState.episode_no} Successfully Published!**`,
  `🎬 **SEO Title:** ${meta.primary_title} (\`${meta.youtube_format}\`)`,
  `📌 **Pinned Comment Draft:** ${meta.pinned_comment}`,
  ``, `🌐 **Live Distribution Links:**`,
  `• **YouTube:** ${pubs.youtube || 'Not Requested'}`,
  `• **Instagram Reels:** ${pubs.instagram || 'Not Requested'}`,
  `• **Telegram Premiere:** ${finalState.final_tg_msg_id ? 'Sent successfully' : 'Not Requested'}`,
  finalState.skipped_platforms.length > 0 ? `• **Idempotent Skipped (Already Live):** ${finalState.skipped_platforms.join(', ')}` : ''
].filter(Boolean).join('\n');

return {
  json: {
    ok: true, status: 'PUBLISHED', workflow_name: 'WF-07', execution_id: $execution.id, project_id: finalState.project_id, episode_no: finalState.episode_no,
    published_at: finalState.published_at, published_platforms: finalState.pending_platforms, skipped_platforms: finalState.skipped_platforms,
    publication_urls: pubs, viral_metadata: meta, output: successMsg, text: successMsg
  }
};

